public sealed class AttemptCache(IMemoryCache memory, IConnectionMultiplexer redis)
{
    public async ValueTask<string?> GetPayloadAsync(
        string attemptId, CancellationToken cancellationToken)
    {
        if (memory.TryGetValue(attemptId, out string? cached))
        {
            return cached; // sync path — no Task allocation
        }

        var db = redis.GetDatabase();
        var payload = await db.StringGetAsync(attemptId);
        cancellationToken.ThrowIfCancellationRequested();
        if (payload.IsNullOrEmpty) return null;

        memory.Set(attemptId, payload.ToString(), TimeSpan.FromSeconds(30));
        return payload.ToString();
    }
}

